  @Test
  public void testNumberLiteralNumberSerializationNonfinite() throws IOException {
    for (double value : new double[] {Double.POSITIVE_INFINITY, Double.NEGATIVE_INFINITY, Double.NaN}) {
      final NumberLiteral instance =
        Jsonization.Deserialize.deserializeNumberLiteral(
          loadTheFirstExpected("NumberLiteral"));

      instance.setNumber(value);

      try {
        Jsonization.Serialize.toJsonObject(instance);
        fail(
          "Expected the serialization to fail at "
            + "getNumber()"
            + ", but it succeeded");
      } catch (Jsonization.SerializeException exception) {
        assertEquals(
          "getNumber()",
          exception.getPath().orElse(null));
      }
    }
  } // public void testNumberLiteralNumberSerializationNonfinite
